// Generated by vibelang from bench/cerebras-load/report.ts; the migrate flow writes it again with each batch.
import { readFileSync, writeFileSync } from 'node:fs';
import { relative } from 'node:path';
export function report(directory) {
    const raw = JSON.parse(readFileSync(`${directory}/raw.json`, 'utf8'));
    const f = (v) => v === null ? 'n/a' : v.toFixed(1);
    const table = ['| Concurrent | Requests/s | OK / 429 / other | TTFT p50/p95/p99 ms | Total p50/p95/p99 ms | Output tok/s | Est. USD |', '|---:|---:|---:|---|---|---:|---:|', ...raw.steps.map((s) => `| ${s.concurrency} | ${f(s.requestsPerSecond)} | ${s.successes} / ${s.errors429} / ${s.otherErrors} | ${Object.values(s.ttftMs).map(f).join('/')} | ${Object.values(s.totalMs).map(f).join('/')} | ${f(s.outputTokensPerSecond)} | ${s.estimatedUsd.toFixed(4)} |`)].join('\n');
    const failures = raw.requests.filter((r) => !r.success);
    const h2 = failures.filter((r) => r.transportCode === 'ERR_HTTP2_INVALID_SESSION').length;
    const diagnosis = h2 ? `HTTP/2 client transport failed: ${h2} attempts reported ERR_HTTP2_INVALID_SESSION. Other failures may have occurred mid-stream; see raw timing. These failures do not establish provider saturation. ` : '';
    const text = `# ${raw.provider ?? 'cerebras'} load test

${relative(process.cwd(), directory)}

${diagnosis}Stopped: ${raw.stopReason}. Charged token upper bound: ${raw.chargedTokens}; estimated USD ${raw.estimatedUsd.toFixed(5)}. Campaign estimate (including outstanding reservations): $${raw.campaignEstimatedUsd ?? 'unrecorded'}.

${table}

## Method and limits

Route: ${JSON.stringify(raw.model)}. Closed-loop workers; ${raw.seconds}s admission per level, then drain, 45s request deadline. Actual levels appear above. Context: ${raw.context}; cache condition: ${raw.cache}. The synthetic agent-size context repeats a project description 130 times; actual tokens are in requests.jsonl. This does not substitute for agent evals. Warm means a repeated prefix, not a guaranteed cache hit; cachedInputTokens records provider usage when available. Cold varies a nonce at the start. Max output 256, reasoning effort none; TTFT includes the first text or thinking delta.

Every probe is a recorded @smthrs/flow action using HostModel and the shared Node provider HTTP/1.1 transport. No benchmark retry. Stop escalation above 20% errors. Successful-call latency excludes refusals; raw rows retain all outcomes and allowlisted rate-limit headers. No prompts, outputs, keys or provider error bodies are logged.

The persistent provider campaign ledger reserves prompt UTF-8 bytes plus 4096 input tokens and 256 output tokens at reviewed list prices before dispatch. Campaign ceiling: $${raw.campaignCapUsd ?? 'unrecorded'}/provider, including outstanding reservations across restarts; ${raw.phase ?? 'unrecorded'} phase ceiling: $${raw.phaseCapUsd ?? 'unrecorded'}. An exclusive lock refuses competing processes. Known usage settles; clean pre-output 4xx refunds; unknown usage retains the upper bound. See providers.ts for price sources and README.md for reproduction. This estimated cap is not an invoice guarantee.

One Mac, one network region and one time window. Closed-loop scheduling, SQLite/ledger overhead, shared account traffic and short outputs limit extrapolation. Unreached levels are unmeasured. No production-capacity or quality claim follows from this test alone.
`;
    writeFileSync(`${directory}/RESULTS.md`, text);
}
